"""Two curves, not one: projection and discounting, and the check that cannot see the
difference between them.

WHY this exists: since collateralised swaps are discounted at the CSA rate, a swap needs TWO
curves -- one to project the floating coupons and one to discount every cash flow. Building a
single-curve model and calling it multi-curve is easy, and the standard sanity check does not
catch it:

  * THE PAR SWAP RATE IS A DISCOUNT-WEIGHTED AVERAGE OF THE PROJECTED FORWARDS.
        S = sum(tau_i f_i D_i) / sum(tau_j D_j)
    Change the discount curve and you change only the WEIGHTS. On a flat forward curve the
    weights cancel exactly and S does not move at all; on an ordinary curve it moves a
    fraction of a basis point. So "does the swap reprice at par?" is nearly blind to the
    discount curve.

  * THE ANNUITY IS A LEVEL, NOT AN AVERAGE. A = sum(tau_j D_j) moves by the full discounting
    difference. Every PV01, every hedge ratio, every swaption numeraire and every off-market
    NPV is scaled by that factor -- and the par-rate check said everything was fine.

  * A QUANTLIB HANDLE IS A LIVE REFERENCE. Rate helpers built against a discount handle
    re-bootstrap when that handle is relinked, so changing the discount curve silently changes
    the PROJECTION curve too, and every object already built moves with it.

The reference implementation here is a plain discount-factor curve, so the QuantLib comparison
is a real check and not a restatement.

Usage:
    from multi_curve import Curve, par_swap_rate, annuity, swap_npv, discounting_comparison
"""
from __future__ import annotations

import math
from typing import Sequence

import numpy as np

# 12 CFR 253.4(c)'s three-month tenor spread adjustment, used here as a realistic constant
# term-vs-overnight basis. Nothing depends on the exact value; see the sensitivity table.
DEFAULT_BASIS = 0.0026161


class Curve:
    """A zero-rate curve with continuous compounding, log-linear on discount factors.

    Log-linear on DFs is piecewise-CONSTANT instantaneous forwards -- the honest default for a
    discount curve, and the one whose forwards do not oscillate.
    """

    def __init__(self, times: Sequence[float], zeros: Sequence[float], spread: float = 0.0):
        t = np.asarray(times, dtype=float)
        z = np.asarray(zeros, dtype=float) + spread
        if t.ndim != 1 or t.shape != z.shape:
            raise ValueError("times and zeros must be one-dimensional and the same length")
        if np.any(np.diff(t) <= 0) or t[0] <= 0:
            raise ValueError("times must be positive and strictly increasing")
        self.times, self.zeros, self.spread = t, z, spread
        self._logdf = -t * z                      # ln D(t) at the pillars

    def log_discount(self, t: float) -> float:
        if t < 0:
            raise ValueError("t must not be negative")
        if t == 0.0:
            return 0.0
        return float(np.interp(t, np.concatenate(([0.0], self.times)),
                               np.concatenate(([0.0], self._logdf))))

    def discount(self, t: float) -> float:
        return math.exp(self.log_discount(t))

    def zero(self, t: float) -> float:
        return -self.log_discount(t) / t if t > 0 else float(self.zeros[0])

    def forward(self, t0: float, t1: float) -> float:
        """The SIMPLE forward rate over [t0, t1) implied by the discount factors."""
        if t1 <= t0:
            raise ValueError("t1 must exceed t0")
        return (self.discount(t0) / self.discount(t1) - 1.0) / (t1 - t0)

    def shifted(self, bp: float) -> "Curve":
        """A parallel shift of the zero curve, in basis points."""
        return Curve(self.times, self.zeros, bp * 1e-4)


def flat_curve(rate: float, horizon: float = 40.0) -> Curve:
    return Curve([0.25, horizon], [rate, rate])


# ------------------------------------------------------------------ swap plumbing
def schedule(tenor_years: float, freq: int) -> tuple[np.ndarray, np.ndarray]:
    """(payment times, accrual fractions) for a leg. Accruals are exact 1/freq years -- the
    day-count layer belongs to bond-conventions-and-accrued, not here."""
    if freq <= 0 or tenor_years <= 0:
        raise ValueError("tenor and frequency must be positive")
    n = int(round(tenor_years * freq))
    times = np.arange(1, n + 1, dtype=float) / freq
    return times, np.full(n, 1.0 / freq)


def annuity(discount: Curve, tenor_years: float = 10.0, fixed_freq: int = 2) -> float:
    """A = sum(tau_j D(T_j)) -- the PV of one unit of fixed rate. A LEVEL."""
    times, taus = schedule(tenor_years, fixed_freq)
    return float(sum(tau * discount.discount(t) for t, tau in zip(times, taus)))


def floating_leg_pv(projection: Curve, discount: Curve, tenor_years: float = 10.0,
                    float_freq: int = 4) -> float:
    """sum(tau_i f_i D(T_i)) with f_i off the PROJECTION curve and D off the DISCOUNT curve."""
    times, taus = schedule(tenor_years, float_freq)
    pv = 0.0
    prev = 0.0
    for t, tau in zip(times, taus):
        f = projection.forward(prev, t)
        pv += tau * f * discount.discount(t)
        prev = t
    return pv


def par_swap_rate(projection: Curve, discount: Curve, tenor_years: float = 10.0,
                  fixed_freq: int = 2, float_freq: int = 4) -> float:
    """S = floating leg PV / annuity: a DISCOUNT-WEIGHTED AVERAGE of the projected forwards."""
    return floating_leg_pv(projection, discount, tenor_years, float_freq) / \
        annuity(discount, tenor_years, fixed_freq)


def swap_npv(fixed_rate: float, notional: float, projection: Curve, discount: Curve,
             tenor_years: float = 10.0, fixed_freq: int = 2, float_freq: int = 4,
             pay_fixed: bool = True) -> float:
    """NPV to the fixed payer = (S - K) x A x N."""
    s = par_swap_rate(projection, discount, tenor_years, fixed_freq, float_freq)
    a = annuity(discount, tenor_years, fixed_freq)
    npv = (s - fixed_rate) * a * notional
    return npv if pay_fixed else -npv


def pv01(notional: float, discount: Curve, tenor_years: float = 10.0,
         fixed_freq: int = 2) -> float:
    """The PV of one basis point on the fixed leg = A x 1e-4 x N."""
    return annuity(discount, tenor_years, fixed_freq) * 1e-4 * notional


# ------------------------------------------------------------------ the comparison
def discounting_comparison(ois: Curve, projection: Curve, tenor_years: float = 10.0,
                           notional: float = 100_000_000.0, strike: float = 0.0450,
                           fixed_freq: int = 2, float_freq: int = 4) -> dict:
    """Price the SAME swap discounting at OIS and at the projection curve.

    Returns the par rate, the annuity, the PV01 and the off-market NPV under each, and what
    the difference is worth.
    """
    out = {}
    for label, disc in (("ois", ois), ("projection", projection)):
        out[label] = {
            "par_rate": par_swap_rate(projection, disc, tenor_years, fixed_freq, float_freq),
            "annuity": annuity(disc, tenor_years, fixed_freq),
            "pv01": pv01(notional, disc, tenor_years, fixed_freq),
            "npv": swap_npv(strike, notional, projection, disc, tenor_years, fixed_freq,
                            float_freq)}
    a_ois, a_prj = out["ois"]["annuity"], out["projection"]["annuity"]
    out["bp_par_rate"] = 1e4 * (out["projection"]["par_rate"] - out["ois"]["par_rate"])
    out["pct_annuity"] = 100.0 * (a_prj / a_ois - 1.0)
    out["pct_pv01"] = 100.0 * (out["projection"]["pv01"] / out["ois"]["pv01"] - 1.0)
    out["npv_error"] = out["projection"]["npv"] - out["ois"]["npv"]
    out["pv01_error"] = out["projection"]["pv01"] - out["ois"]["pv01"]
    return out


def reprices_at_par(projection: Curve, discount: Curve, tenor_years: float = 10.0,
                    notional: float = 100_000_000.0, fixed_freq: int = 2,
                    float_freq: int = 4) -> float:
    """The check people actually run: price a swap struck at its own par rate. It returns
    approximately zero under EVERY discount curve, which is the problem."""
    s = par_swap_rate(projection, discount, tenor_years, fixed_freq, float_freq)
    return swap_npv(s, notional, projection, discount, tenor_years, fixed_freq, float_freq)


def basis_sensitivity(ois: Curve, bases_bp: Sequence[float], tenor_years: float = 10.0,
                      notional: float = 100_000_000.0, strike: float = 0.0450) -> list[dict]:
    rows = []
    for b in bases_bp:
        proj = Curve(ois.times, ois.zeros, b * 1e-4)
        c = discounting_comparison(ois, proj, tenor_years, notional, strike)
        rows.append({"basis_bp": b, "bp_par_rate": c["bp_par_rate"],
                     "pct_annuity": c["pct_annuity"], "npv_error": c["npv_error"],
                     "pv01_error": c["pv01_error"], "par_rate": c["ois"]["par_rate"]})
    return rows


# ------------------------------------------------------------------ QuantLib
def quantlib_cross_checks(ois_zeros: Sequence[tuple[float, float]], basis: float,
                          tenor_years: int = 10, notional: float = 100_000_000.0,
                          strike: float = 0.0450) -> dict | None:
    """Build both curves in QuantLib behind RelinkableYieldTermStructureHandles, price the
    same swap under each discounting, and show what relinking a handle does to objects that
    were built before it. Returns None if QuantLib is not installed."""
    try:
        import QuantLib as ql
    except ImportError:
        return None
    today = ql.Date(15, 1, 2026)
    ql.Settings.instance().evaluationDate = today
    cal = ql.UnitedStates(ql.UnitedStates.GovernmentBond)
    dc = ql.Actual365Fixed()

    def build(spread):
        dates = [today] + [today + ql.Period(int(round(t * 12)), ql.Months)
                           for t, _ in ois_zeros]
        rates = [ois_zeros[0][1] + spread] + [z + spread for _, z in ois_zeros]
        return ql.ZeroCurve(dates, rates, dc, cal, ql.Linear(), ql.Continuous, ql.Annual)

    ois_curve, proj_curve = build(0.0), build(basis)
    ois_h = ql.RelinkableYieldTermStructureHandle(ois_curve)
    proj_h = ql.RelinkableYieldTermStructureHandle(proj_curve)
    index = ql.IborIndex("PROJ-3M", ql.Period(3, ql.Months), 2, ql.USDCurrency(), cal,
                         ql.ModifiedFollowing, False, ql.Actual360(), proj_h)
    start = cal.advance(today, 2, ql.Days)
    end = cal.advance(start, ql.Period(tenor_years, ql.Years))
    fixed_sch = ql.Schedule(start, end, ql.Period(ql.Semiannual), cal, ql.ModifiedFollowing,
                            ql.ModifiedFollowing, ql.DateGeneration.Forward, False)
    float_sch = ql.Schedule(start, end, ql.Period(ql.Quarterly), cal, ql.ModifiedFollowing,
                            ql.ModifiedFollowing, ql.DateGeneration.Forward, False)
    swap = ql.VanillaSwap(ql.Swap.Payer, notional, fixed_sch, strike, ql.Thirty360(
        ql.Thirty360.BondBasis), float_sch, index, 0.0, ql.Actual360())

    out: dict = {"version": ql.__version__}
    for label, handle in (("ois", ois_h), ("projection", proj_h)):
        swap.setPricingEngine(ql.DiscountingSwapEngine(handle))
        out[label] = {"par_rate": swap.fairRate(), "npv": swap.NPV(),
                      "annuity": abs(swap.fixedLegBPS()) * 1e4 / notional,
                      "bps": swap.fixedLegBPS()}
    out["bp_par_rate"] = 1e4 * (out["projection"]["par_rate"] - out["ois"]["par_rate"])
    out["pct_annuity"] = 100.0 * (out["projection"]["annuity"] / out["ois"]["annuity"] - 1.0)
    out["npv_error"] = out["projection"]["npv"] - out["ois"]["npv"]

    # A relinkable handle is a LIVE reference: relinking it moves every object built from it.
    swap.setPricingEngine(ql.DiscountingSwapEngine(ois_h))
    before = swap.NPV()
    ois_h.linkTo(build(0.0010))                   # +10 bp on the OIS curve only
    out["npv_after_relink"] = swap.NPV()
    out["npv_before_relink"] = before
    ois_h.linkTo(ois_curve)

    # And a stale evaluation date silently gives NPV exactly 0.0 once the swap has expired.
    ql.Settings.instance().evaluationDate = end + ql.Period(1, ql.Days)
    out["npv_after_maturity"] = swap.NPV()
    ql.Settings.instance().evaluationDate = today
    return out


# ------------------------------------------------------------------ demo
if __name__ == "__main__":
    W = 94
    TIMES = (0.5, 1.0, 2.0, 3.0, 5.0, 7.0, 10.0, 15.0, 20.0, 30.0)
    ZEROS = (0.0290, 0.0295, 0.0305, 0.0315, 0.0330, 0.0340, 0.0348, 0.0355, 0.0358, 0.0360)
    NOTIONAL, STRIKE, TENOR = 100_000_000.0, 0.0450, 10.0
    ois = Curve(TIMES, ZEROS)
    proj = Curve(TIMES, ZEROS, DEFAULT_BASIS)

    print("=" * W)
    print(f"OIS DISCOUNTING AND MULTI-CURVE -- a {TENOR:.0f}y swap, {NOTIONAL:,.0f} notional, "
          f"K = {STRIKE:.2%}")
    print(f"OIS zero curve {ZEROS[0]:.2%} to {ZEROS[-1]:.2%}; projection curve = OIS + "
          f"{DEFAULT_BASIS * 1e4:.3f} bp")
    print("=" * W)

    print("\n1. THE CHECK EVERYONE RUNS, UNDER BOTH DISCOUNT CURVES")
    for label, disc in (("OIS discounting      ", ois), ("projection discounting", proj)):
        s = par_swap_rate(proj, disc, TENOR)
        print(f"   {label}: par rate {s:.8%}   swap struck at its own par rate prices at "
              f"{reprices_at_par(proj, disc, TENOR, NOTIONAL):+.2e}")
    print("   -> BOTH reprice at par. The check has no power to distinguish them.")

    print("\n2. WHAT ACTUALLY MOVED")
    c = discounting_comparison(ois, proj, TENOR, NOTIONAL, STRIKE)
    print(f"   {'':<24}{'OIS discounting':>20}{'projection disc.':>20}{'difference':>18}")
    print(f"   {'par swap rate':<24}{c['ois']['par_rate']:>20.8%}"
          f"{c['projection']['par_rate']:>20.8%}{c['bp_par_rate']:>+17.3f} bp")
    print(f"   {'annuity (years)':<24}{c['ois']['annuity']:>20.8f}"
          f"{c['projection']['annuity']:>20.8f}{c['pct_annuity']:>+17.3f} %")
    print(f"   {'PV01':<24}{c['ois']['pv01']:>20,.2f}{c['projection']['pv01']:>20,.2f}"
          f"{c['pv01_error']:>+18,.2f}")
    print(f"   {'NPV at K = ' + f'{STRIKE:.2%}':<24}{c['ois']['npv']:>20,.2f}"
          f"{c['projection']['npv']:>20,.2f}{c['npv_error']:>+18,.2f}")
    print(f"   -> the par rate moved {abs(c['bp_par_rate']):.3f} bp and the annuity moved "
          f"{abs(c['pct_annuity']):.3f}%")
    print(f"   -> that {abs(c['pct_annuity']):.3f}% scales EVERY PV01, hedge ratio, swaption "
          f"numeraire and off-market NPV")
    print(f"   -> on this swap it is {abs(c['npv_error']):,.2f} of NPV and "
          f"{abs(c['pv01_error']):,.2f} of PV01, on {NOTIONAL:,.0f}")

    print("\n3. WHY THE PAR RATE CANNOT SEE IT: S IS A WEIGHTED AVERAGE, A IS A LEVEL")
    flat = flat_curve(0.0330)
    flat_p = Curve(flat.times, flat.zeros, DEFAULT_BASIS)
    s_a = par_swap_rate(flat_p, flat, TENOR, 4, 4)
    s_b = par_swap_rate(flat_p, flat_p, TENOR, 4, 4)
    print(f"   FLAT forwards, fixed and floating on the SAME quarterly schedule:")
    print(f"     par rate {s_a:.10%} vs {s_b:.10%}   difference {1e4 * (s_b - s_a):+.8f} bp")
    print(f"     annuity  {annuity(flat, TENOR, 4):.8f} vs {annuity(flat_p, TENOR, 4):.8f}"
          f"   difference {100 * (annuity(flat_p, TENOR, 4) / annuity(flat, TENOR, 4) - 1):+.4f} %")
    print("   -> S = sum(tau f D) / sum(tau D). With every f equal and the SAME dates in both")
    print("      sums, the D's cancel EXACTLY: the par rate is invariant to the discount curve.")
    s_c = par_swap_rate(flat_p, flat, TENOR, 2, 4)
    s_d = par_swap_rate(flat_p, flat_p, TENOR, 2, 4)
    print(f"   the same curve with a SEMIANNUAL fixed leg against a QUARTERLY float leg:")
    print(f"     par rate {s_c:.10%} vs {s_d:.10%}   difference {1e4 * (s_d - s_c):+.6f} bp")
    print(f"   -> the schedule mismatch leaves a {abs(1e4 * (s_d - s_c)):.3f} bp residual on a "
          f"curve where the annuity moved "
          f"{abs(100 * (annuity(flat_p, TENOR, 4) / annuity(flat, TENOR, 4) - 1)):.4f}%.")
    print("      The par-rate check is not imprecise; it is looking at the wrong quantity.")

    print("\n4. IT SCALES WITH THE BASIS, AND THE PAR RATE NEVER NOTICES")
    print(f"   {'basis (bp)':>12}{'par rate S':>13}{'d(par) bp':>12}{'annuity (%)':>14}"
          f"{'PV01 error':>14}{'NPV error':>14}")
    for r in basis_sensitivity(ois, (5, 10, 26.161, 50, 100), TENOR, NOTIONAL, STRIKE):
        print(f"   {r['basis_bp']:>12.3f}{r['par_rate']:>13.4%}{r['bp_par_rate']:>+12.3f}"
              f"{r['pct_annuity']:>+14.3f}{r['pv01_error']:>+14,.0f}{r['npv_error']:>+14,.0f}")
    print("   -> a 100 bp basis moves the par rate by hundredths of a basis point and the")
    print("      annuity by several percent. The two are not in the same units of wrongness.")
    print(f"   -> the NPV error is (S - K) x dA, so it VANISHES at the money (S -> K = "
          f"{STRIKE:.2%} near a 100 bp basis) and grows the further off-market you are. The")
    print("      PV01 error does not vanish anywhere.")

    print("\n5. CROSS-CHECK AGAINST QUANTLIB")
    live = quantlib_cross_checks(list(zip(TIMES, ZEROS)), DEFAULT_BASIS, int(TENOR), NOTIONAL,
                                 STRIKE)
    if live is None:
        print("   QuantLib not installed - the reference implementation above stands alone")
    else:
        print(f"   QuantLib {live['version']}  (VanillaSwap + DiscountingSwapEngine)")
        print(f"   {'':<24}{'OIS discounting':>20}{'projection disc.':>20}"
              f"{'difference':>18}")
        print(f"   {'fairRate()':<24}{live['ois']['par_rate']:>20.8%}"
              f"{live['projection']['par_rate']:>20.8%}{live['bp_par_rate']:>+17.3f} bp")
        print(f"   {'annuity from fixedLegBPS':<24}{live['ois']['annuity']:>20.8f}"
              f"{live['projection']['annuity']:>20.8f}{live['pct_annuity']:>+17.3f} %")
        print(f"   {'NPV':<24}{live['ois']['npv']:>20,.2f}{live['projection']['npv']:>20,.2f}"
              f"{live['npv_error']:>+18,.2f}")
        print(f"   -> QuantLib reproduces the shape: par rate {abs(live['bp_par_rate']):.3f} bp,"
              f" annuity {abs(live['pct_annuity']):.3f}%, NPV {abs(live['npv_error']):,.0f}")
        print(f"   -> RELINKING THE DISCOUNT HANDLE by +10 bp moves an ALREADY BUILT swap's NPV "
              f"from {live['npv_before_relink']:,.2f} to {live['npv_after_relink']:,.2f} "
              f"({live['npv_after_relink'] - live['npv_before_relink']:+,.2f}) with no "
              f"recalculation call")
        print(f"   -> and pushing evaluationDate past maturity gives NPV = "
              f"{live['npv_after_maturity']:.1f} -- exactly zero, no error")

    print("\n" + "=" * W)
    print("RULE: the par swap rate is a DISCOUNT-WEIGHTED AVERAGE of the forwards and barely")
    print("      moves when you change the discount curve; the ANNUITY is a level and moves by")
    print("      the whole basis. Check the annuity, not the par rate.")
    print("=" * W)
